import { readFile } from "node:fs/promises";

const usage = `Usage: node tools/report.mjs <command> [options]

Commands:
  scan --input <path>  Report the input path and file size as JSON

Options:
  --input <path>       Required for scan
  -h, --help           Show this help`;

async function main() {
  const args = process.argv.slice(2);

  if (args.includes("--help") || args.includes("-h")) {
    console.log(usage);
    return;
  }

  const [command, ...options] = args;
  if (command !== "scan") {
    throw new Error("expected command 'scan'; use --help for usage");
  }

  if (options.length !== 2 || options[0] !== "--input" || !options[1]) {
    throw new Error("scan requires --input <path>; use --help for usage");
  }

  const input = options[1];
  const contents = await readFile(input);
  console.log(JSON.stringify({ input, bytes: contents.length }));
}

main().catch((error) => {
  console.error(`report: ${error.message}`);
  process.exitCode = 1;
});

